marker='// Apply V7.0 overrides after all V6.x assignments have executed.'
assert marker in s
v71_js=r'''/* =========================================================\n   V7.1 Growth Summary — final local-state overrides\n   ========================================================= */\nwindow.__QZL_VERSION='7.1';\n\nfunction inferGrowthResult(action){\n  if(!action||action.status==='pending')return null;\n  if(['better','same','worse'].includes(action.result))return action.result;\n  const t=String(action.resultText||'');\n  if(t.includes('顺'))return 'better';\n  if(t.includes('糟')||t.includes('差'))return 'worse';\n  if(t.includes('没')||t.includes('变化')||t.includes('一般'))return 'same';\n  return 'same';\n}\nfunction normalizeGrowthActions(){\n  if(!state||!Array.isArray(state.actions))return;\n  const defaults=new Map(DEFAULT_ACTIONS.map(a=>[a.id,a]));\n  state.actions=state.actions.map(raw=>{\n    const seed=defaults.get(raw?.id)||{};\n    const a={...seed,...raw};\n    a.id=a.id||uid('action');a.date=a.date||'2026-09-03';a.title=a.title||'一个新的小行动';a.source=a.source||'和小亲的对话';\n    a.why=a.why||'先降低互动压力，再观察真正卡住的地方。';\n    a.script=a.script||'“我先听你说，不急着马上解决。”';\n    a.observe=a.observe||'观察双方的情绪是否更容易稳定下来。';\n    a.status=a.status==='done'?'done':'pending';\n    if(a.status==='pending'){a.result=null;a.resultText='待尝试';}\n    else{a.result=inferGrowthResult(a);if(!a.resultText||a.resultText==='待尝试')a.resultText=V70_RESULT_META[a.result]?.label||'已反馈';}\n    return a;\n  });\n  state.growth=state.growth&&typeof state.growth==='object'?state.growth:{};\n  state.growth.month=state.growth.month||'2026-08';\n  state.growth.view=['week','month','all'].includes(state.growth.view)?state.growth.view:'week';\n  if(state.growth.selectedDate===undefined)state.growth.selectedDate='2026-08-26';\n}\n\nv70Status=function(action){if(!action||action.status==='pending')return {key:'pending',label:'待尝试'};return V70_RESULT_META[action.result]||{key:'same',label:action.resultText||'已反馈'};};\nv70FeedbackIcon=function(key){return v70StatusIcon(key);};\nv70StatsHtml=function(){const s=getGrowthStats();return `<div class="v71-hero-stats"><b>${s.conversationCount} 次聊过</b><i>·</i><b>${s.actionCount} 个行动</b><i>·</i><b>${s.feedbackCount} 次反馈</b></div><div class="v71-streak">已连续留下 ${s.recordDays} 天记录</div>`;};\nfunction v71HeroHtml(mode){const monthly=mode==='month';return `<section class="v71-growth-hero"><div class="v71-hero-head"><i class="v71-hero-icon">${svg.growth}</i><span class="v71-hero-id"><b>小亲</b><span>情绪价值 · 成长陪伴</span></span></div><h1>${monthly?'这个月，你正在把理解慢慢积累成改变':'你正在把理解慢慢变成新的回应'}</h1><p>${monthly?'把行动放回时间里看，比一次结果更容易看见真正的变化。':'变化不一定很快，但每一次愿意停一下、先听懂发生了什么，都会留下痕迹。'}</p><div id="growthStatsSlot">${v70StatsHtml()}</div></section>`;}\nfunction v71HighlightsHtml(){return `<section class="v70-section"><div class="v70-section-head"><h2>本周亮点</h2><span>小亲为你整理</span></div><div class="v70-highlights"><div class="v70-highlight green"><i>${svg.sprout}</i><div><b>更关注孩子的情绪</b><p>几次冲突里，你开始把“马上纠正”换成先听发生了什么。</p></div></div><div class="v70-highlight peach"><i>${svg.heart}</i><div><b>更早觉察自己的压力</b><p>你已经能更快看到自己开始着急的那个瞬间。</p></div></div></div></section>`;}\nfunction v71CalendarSection(){return `<section class="v71-calendar-section"><div class="v70-calendar-card" id="growthCalendarSlot">${v70CalendarHtml()}</div></section>`;}\nv70ActionHtml=function(){\n  const a=v70SelectedAction();const date=state.growth.selectedDate;\n  if(!a){return `<header><span><b>${date?esc(formatActionDate(date)):'当前行动'}</b><small>${date?'今天的行动':'选择日期查看'}</small></span><time></time></header><div class="v70-empty"><b>${date?'这一天没有行动记录':'先从日历选择一个日期'}</b><p>${date?'这是一个真正的空日期，不会显示其他日期的行动。':'日历里的状态点代表已经产生过行动。'}</p></div>`;}\n  const feedbackLabel=a.status==='pending'?'试过了':'修改反馈';\n  return `<header><span><b>${esc(formatActionDate(a.date))}</b><small>今天的行动</small></span><time>${esc(v70Status(a).label)}</time></header><div class="v70-action-main"><i class="v70-action-icon">${svg.sprout}</i><div><b>${esc(a.title)}</b><p>来源：${esc(a.source)}</p></div></div><div class="v70-inline-actions"><button class="primary" data-action="action-feedback" data-id="${a.id}">${feedbackLabel}</button>${a.status==='pending'?'<button class="secondary" data-action="not-tried">还没试</button>':''}<button class="secondary" data-action="growth-action-detail" data-id="${a.id}">查看详情</button>${a.status==='done'?`<button class="secondary" data-action="review-action" data-id="${a.id}">和小亲复盘</button>`:''}</div>`;\n};\nrenderGrowthRecordRowV70=function(a){const meta=v70Status(a);return `<button class="v70-record" data-action="growth-action-select" data-id="${a.id}"><i class="v70-record-icon ${meta.key}">${v70StatusIcon(meta.key)}</i><span class="v70-record-main"><b>${esc(a.title)}</b><span>${esc(formatActionDate(a.date))} · 来源：${esc(a.source)}</span></span><span class="v70-record-status ${meta.key}">${esc(meta.label)}</span></button>`;};\nv70RecentHtml=function(all=false){\n  const selected=v70SelectedAction();let arr=state.actions.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)));\n  if(all&&state.growth.view==='month')arr=arr.filter(a=>String(a.date).slice(0,7)===state.growth.month);\n  if(!all&&selected)arr=arr.filter(a=>a.id!==selected.id);\n  if(!all)arr=arr.slice(0,2);\n  return `<div class="v70-record-list">${arr.map(renderGrowthRecordRowV70).join('')||'<div class="v70-empty"><b>还没有行动记录</b><p>新的行动会在对话里产生。</p></div>'}</div>${!all&&state.actions.length>2?'<button class="v70-more" data-action="growth-view" data-value="all">查看全部行动 ›</button>':''}`;\n};\nv70WeekContent=function(){return `${v71HeroHtml('week')}${v71HighlightsHtml()}${v71CalendarSection()}<section class="v71-action-section" id="growthActionSection"><div class="v70-action-card" id="growthActionSlot">${v70ActionHtml()}</div></section><section class="v70-section"><div class="v70-section-head"><h2>最近行动</h2><span>点击原地定位</span></div><div id="growthRecentSlot">${v70RecentHtml(false)}</div></section>`;};\nv70MonthContent=function(){return `${v71HeroHtml('month')}${v71CalendarSection()}<section class="v71-action-section" id="growthActionSection"><div class="v70-action-card" id="growthActionSlot">${v70ActionHtml()}</div></section><section class="v70-section"><div class="v70-section-head"><h2>本月行动</h2><span>${esc(v70MonthLabel())}</span></div><div id="growthRecentSlot">${v70RecentHtml(true)}</div></section>`;};\nv70AllContent=function(){return `<section class="v70-section" style="margin-top:2px"><button class="v71-all-back" data-action="growth-view" data-value="week">${svg.back} 返回成长总结</button><div class="v70-section-head"><h2>全部行动</h2><span>${state.actions.length} 条</span></div><div id="growthRecentSlot">${v70RecentHtml(true)}</div></section>`;};\nrenderGrowthV70=function(){normalizeGrowthActions();state.growth.view=state.growth.view||'week';const view=state.growth.view;return `<div class="secondary-page growth-page v70-growth-page">${titleBar('成长总结',{back:'home'})}<div class="page-body"><div class="v70-growth-tabs"><button class="${view==='week'?'active':''}" data-action="growth-view" data-value="week">周</button><button class="${view==='month'?'active':''}" data-action="growth-view" data-value="month">月</button><button class="${view==='all'?'active':''}" data-action="growth-view" data-value="all">全部</button></div><div id="growthViewSlot">${view==='all'?v70AllContent():view==='month'?v70MonthContent():v70WeekContent()}</div></div></div>`;};\nrefreshGrowthLocal=function(opts={}){\n  if(routeBase(currentRoute)!=='growth')return;\n  const page=document.querySelector('.v70-growth-page');const top=page?page.scrollTop:0;\n  const cal=document.getElementById('growthCalendarSlot');if(cal)cal.innerHTML=v70CalendarHtml();\n  const act=document.getElementById('growthActionSlot');if(act)act.innerHTML=v70ActionHtml();\n  const rec=document.getElementById('growthRecentSlot');if(rec)rec.innerHTML=v70RecentHtml(state.growth.view==='all'||state.growth.view==='month');\n  const stats=document.getElementById('growthStatsSlot');if(stats)stats.innerHTML=v70StatsHtml();\n  if(page&&!opts.scrollAction)page.scrollTop=top;\n  if(opts.scrollAction){const section=document.getElementById('growthActionSection');if(section)setTimeout(()=>section.scrollIntoView({behavior:'smooth',block:'center'}),0);}\n};\nselectGrowthDate=function(date){state.growth.selectedDate=date;saveState();refreshGrowthLocal();};\nselectGrowthAction=function(id){const a=state.actions.find(x=>x.id===id);if(!a)return;state.growth.selectedDate=a.date;state.growth.month=a.date.slice(0,7);saveState();refreshGrowthLocal({scrollAction:true});};\nselectGrowthView=function(view){\n  view=['week','month','all'].includes(view)?view:'week';state.growth.view=view;saveState();\n  if(routeBase(currentRoute)!=='growth')return;\n  document.querySelectorAll('.v70-growth-tabs [data-action="growth-view"]').forEach(btn=>btn.classList.toggle('active',btn.dataset.value===view));\n  const slot=document.getElementById('growthViewSlot');if(!slot)return;slot.innerHTML=view==='all'?v70AllContent():view==='month'?v70MonthContent():v70WeekContent();\n  const page=document.querySelector('.v70-growth-page');if(page)page.scrollTo({top:0,behavior:'auto'});\n};\nchangeMonth=function(delta){const [y,m]=state.growth.month.split('-').map(Number);const d=new Date(y,m-1+delta,1);state.growth.month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;state.growth.selectedDate=null;saveState();if(routeBase(currentRoute)==='growth')refreshGrowthLocal();};\nshowGrowthActionDetail=function(id){const a=state.actions.find(x=>x.id===id);if(!a)return;showBottomSheet(`<div class="v71-growth-sheet v71-detail-sheet"><button class="v71-sheet-close" data-overlay-action="close" aria-label="关闭">${svg.close}</button><h2>${esc(a.title)}</h2><div class="sheet-sub">${esc(formatActionDate(a.date))} · 来源：${esc(a.source)}</div><div class="v70-detail-block"><b>为什么这样做</b><p>${esc(a.why)}</p></div><div class="v70-detail-block"><b>可以怎么说</b><p>${esc(a.script)}</p></div><div class="v70-detail-block"><b>观察什么</b><p>${esc(a.observe)}</p></div><div class="v70-detail-block"><b>反馈结果</b><p>${esc(a.resultText||'还没有反馈')}</p></div>${a.status==='done'?`<button class="primary-btn full-btn" data-overlay-action="feedback-talk" data-id="${a.id}">和小亲复盘</button>`:''}</div>`);};\nshowActionFeedback=function(id){const a=state.actions.find(x=>x.id===id);if(!a)return;showBottomSheet(`<div class="v71-growth-sheet"><h2 class="sheet-title-with-icon"><span class="sheet-title-icon">${svg.sprout}</span>记录这次尝试</h2><div class="sheet-sub">不用评价自己，只记录这次发生了什么。</div><button class="sheet-option v70-feedback-option" data-overlay-action="feedback-result" data-id="${a.id}" data-result="better" data-text="顺一点"><i class="v70-feedback-icon better">${v70FeedbackIcon('better')}</i><span><b>顺一点</b><small>有一点点变化，值得继续观察</small></span></button><button class="sheet-option v70-feedback-option" data-overlay-action="feedback-result" data-id="${a.id}" data-result="same" data-text="没变化"><i class="v70-feedback-icon same">${v70FeedbackIcon('same')}</i><span><b>没变化</b><small>暂时看不出差别，也是一条重要记录</small></span></button><button class="sheet-option v70-feedback-option" data-overlay-action="feedback-result" data-id="${a.id}" data-result="worse" data-text="更糟"><i class="v70-feedback-icon worse">${v70FeedbackIcon('worse')}</i><span><b>更糟</b><small>这次更难受，我们可以一起复盘原因</small></span></button><button class="sheet-footer-btn" data-overlay-action="feedback-talk" data-id="${a.id}">想和小亲具体聊聊</button></div>`);};\nrecordActionResult=function(id,result,text){const a=state.actions.find(x=>x.id===id);if(!a)return;a.status='done';a.result=['better','same','worse'].includes(result)?result:'same';a.resultText=text||V70_RESULT_META[a.result]?.label||'已反馈';state.growth.selectedDate=a.date;state.growth.month=a.date.slice(0,7);saveState();closeOverlay();if(routeBase(currentRoute)==='growth')refreshGrowthLocal();toast('已记录：'+a.resultText);};\n\n'''
v71_js=v71_js.replace('\\n','\n')
s=s.replace(marker,v71_js+marker,1)

# Final initialization after assignments.
final_assign="""renderGrowth=renderGrowthV70;\nrenderCalendar=renderCalendarV70;\nrenderGrowthRecordRow=renderGrowthRecordRowV70;\n\n})();"""
final_init="""renderGrowth=renderGrowthV70;\nrenderCalendar=renderCalendarV70;\nrenderGrowthRecordRow=renderGrowthRecordRowV70;\n\n/* V7.1: initialize only after the latest render/interaction overrides are active. */\nnormalizeGrowthActions();\nmigrateCenterState();\nsaveState();\nrenderRoute(normalizeRoute());\nsyncDebug();\nsetDrawerProgress(0);\n\n})();"""
assert final_assign in s
s=s.replace(final_assign,final_init,1)

# Any remaining system feedback emoji means a growth path still uses system glyphs.
for ch in ('🙂','😐','🙁'):
    if ch in s:
        raise SystemExit(f'Remaining forbidden emoji {ch}: {s.count(ch)}')

# Sanity: no detail map remains, V7.1 marker exists, initialization moved.
assert 'V70_ACTION_DETAILS' not in s
assert "window.__QZL_VERSION='7.1'" in s
assert s.count('renderRoute(normalizeRoute());')==1

out.write_text(s,'utf-8')
print(out)
print('bytes',out.stat().st_size)
